$testName='edupulse_verify_'.date('Ymd_His');$db->exec("CREATE DATABASE `$testName` CHARACTER SET utf8mb4");$db->exec("USE `$testName`");foreach(explode(';',file_get_contents(__DIR__.'/../sql/schema.sql')) as $sql)if(trim($sql))$db->exec($sql);
