$pr=programRows($db,$f);check(count($pr)===3,'three CICS program query results');$rows=subjectRows($db,$f);$attempted=0;$passed=0;foreach($rows as $row){$attempted+=(int)$row['Enrolled']*(int)$row['Units'];$passed+=(int)$row['Enrolled']*(float)$row['Passing (%)']/100*(int)$row['Units'];}check(abs((float)$a['pass_rate']-round(100*$passed/$attempted,1))<.2,'subject passing results reconcile with unit-weighted academic KPI');
$sample=[['A','B','C'],['text, with comma','<&" UTF-8 résumé',''],['1','2','3']];$xlsx=xlsxWrite($sample);check(xlsxRead($xlsx)===$sample,'native XLSX ZIP/XML round trip');check(str_starts_with(pdfWrite($sample),'%PDF-1.4'),'PDF export has valid document header');
