$institution=$data;foreach([1,2] as $i)$institution[$i][0]='PRIVATE-VERIFY-001';$v=validateDataset($db,$institution);$before=academicSummary($db,$f);commitDataset($db,$v['rows'],'institutional','authorized-private.xlsx');$after=academicSummary($db,$f);check($before===$after,'institutional imports never affect public analytics');check((int)$db->query("SELECT COUNT(*) FROM students WHERE public_code='PRIVATE-VERIFY-001' AND synthetic=0")->fetchColumn()===1,'institutional records retain private classification');
// Exercise rollback after writes begin: same student code with conflicting programs.
